import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address keeper, address dnGmxJuniorVault, address sGlp, address usdc, address rewardRouter, address glpManager, uint256 usdcAmount) public {
        // 1. Restrict to plausible addresses; avoid zero to prevent reverts during initialization
        vm.assume(keeper != address(0));
        vm.assume(dnGmxJuniorVault != address(0));
        vm.assume(sGlp != address(0));
        vm.assume(usdc != address(0));
        vm.assume(rewardRouter != address(0));
        vm.assume(glpManager != address(0));

        // Initialize contract; we bypass the complex batching flow by focusing on the pause state directly after executeBatchStake
        // Since executeBatchStake is onlyKeeper and calls _pause(), we need the keeper role; we also need to avoid reverts inside _executeVaultUserBatchStake
        // We mock the minimal required state: give the contract some USDC balance so that executeBatchStake does not revert due to NoUsdcBalance
        // But executeBatchStake calls _stakeGlp which interacts with external contracts; we cannot easily mock those.
        // The property is about paused() after _pause() is called.  The only path that calls _pause() directly is executeBatchStake.
        // To trigger the property without complex mocking, we note that pauseDeposit also calls _pause() but is also onlyKeeper.
        // The simplest invariant: after any keeper calls _pause() indirectly via an authorized path and the call does not revert,
        // paused() must be true.  The mutant always returns false.
        // We can test this by calling pauseDeposit (which is onlyKeeper and calls _pause()) — it has no preconditions except caller == keeper.
        // So we can test: after a successful pauseDeposit, paused() must be true.
        // However, pauseDeposit requires the contract to be initialized. We initialize first.
        // We need to match the initialization interface: initialize(IERC20, IERC20, IRewardRouterV2, IGlpManager, address, address)
        // We have fuzzed addresses that are contracts; but they are EOAs in the fuzzer without code.
        // The initialize function calls IERC20, IRewardRouterV2, IGlpManager interfaces but does not actually call any functions on them except glpManager.vault() during __GMXBatchingManager_init.
        // That call will succeed to an EOA (returns empty bytes) and `IVault(glpManager.vault())` will work (address).
        // So initialization should succeed.
        // Then we set the keeper to the fuzzed keeper.
        // Then we pause via the keeper.
        // Then we assert paused() == true.

        // Perform initialization
        c.initialize(IERC20(sGlp), IERC20(usdc), IRewardRouterV2(rewardRouter), IGlpManager(glpManager), dnGmxJuniorVault, keeper);

        // Ensure caller is owner to set keeper (the initializer sets msg.sender as owner; setUp runs as this contract, so owner is address(this))
        // But we want to test with fuzzed keeper; we set it as owner.
        c.setKeeper(keeper);

        // Now, as the keeper, call pauseDeposit
        vm.prank(keeper);
        c.pauseDeposit();

        // Assert that the contract is paused
        bool isPaused = c.paused();
        assertTrue(isPaused);
    }
}

