contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address _keeper) public {
        // Admissible domain: any non-zero address (zero is allowed but event still expected)
        // Set up state: call setKeeper and capture whether event was emitted
        // In Foundry we can use vm.recordLogs. For the universal property, after setKeeper
