        bool found = false;
        for (uint256 i = 0; i < entries.length; i++) {
            if (entries[i].topics[0] == keeperUpdatedTopic) {
                // Check the indexed parameter _keeper equals what we passed
                bytes32 data = entries[i].topics[1];
                if (data == bytes32(uint256(uint160(_keeper)))) {
                    found = true;
                    break;
                }
            }
        }
