        vm.assume(newKeeper != address(0));
        // The reference emits KeeperUpdated, the mutant does not.
        // We check that the event is actually emitted by inspecting the recorded logs.
        vm.recordLogs();
        vm.prank(address(this));
        c.setKeeper(newKeeper);
        Vm.Log[] memory entries = vm.getRecordedLogs();
        bool keeperUpdatedEmitted = false;
        for (uint i = 0; i < entries.length; i++) {
            if (entries[i].topics[0] == keccak256("KeeperUpdated(address)")) {
                keeperUpdatedEmitted = true;
                break;
            }
        }
        assertTrue(keeperUpdatedEmitted);
    }
}
